8	export function format(
9	  date: Date | number,
10	  options?: Partial<{
11	    locale: string;
12	    style: Intl.RelativeTimeFormatStyle;
13	  }>
14	): string {
15	  const rtf = new Intl.RelativeTimeFormat(options?.locale, {
16	    style: options?.style ?? 'short',
17	  });
18	
19	  const d = typeof date === 'number' ? new Date(date) : date;
20	  const now = Date.now();
21	
22	  const seconds = Math.floor((now - d.getTime()) / 1000);
23	  const minutes = Math.floor(seconds / 60);
24	  const hours = Math.floor(minutes / 60);
25	  const days = Math.floor(hours / 24);
26	  const weeks = Math.floor(days / 7);
27	  const months = Math.floor(weeks / 4);
28	  const years = Math.floor(days / 365);
29	
30	  if (Math.abs(seconds) < 45) {
31	    return new Intl.RelativeTimeFormat(undefined, {
32	      numeric: 'auto',
33	      style: options?.style ?? 'short',
34	    }).format(0, 'seconds');
35	  }
36	
37	  if (Math.abs(minutes) < 60) {
38	    return rtf.format(minutes * -1, 'minutes');
39	  }
40	
41	  if (Math.abs(hours) < 24) {
42	    return rtf.format(hours * -1, 'hours');
43	  }
44	
45	  if (Math.abs(days) < 7) {
46	    return rtf.format(days * -1, 'days');
47	  }
48	
49	  if (Math.abs(weeks) < 4) {
50	    return rtf.format(weeks * -1, 'weeks');
51	  }
52	
53	  if (Math.abs(days) < 365) {
54	    return rtf.format(months * -1, 'months');
55	  }
56	
57	  return rtf.format(years * -1, 'years');
58	}
