81	    options?.timeStyle === null
82	      ? undefined
83	      : (options?.timeStyle ?? options?.style ?? 'medium');
84	
85	  const dateStyle =
86	    options?.dateStyle === null
87	      ? undefined
88	      : (options?.dateStyle ?? options?.style ?? 'long');
89	
90	  const dtf = new Intl.DateTimeFormat(undefined, {
91	    timeStyle,
92	    dateStyle,
93	    timeZone: options?.timeZone,
94	  });
95	
96	  return dtf.formatRange(startDate, endDate);
